using System;
internal static class UsbAdmissionRestartSelectionTest {
 static void Check(bool condition){if(!condition)throw new Exception("Restart selection regression");}
 static UsbAdmissionPreflight.Input Item(string name,string connector){return new UsbAdmissionPreflight.Input{Instance=@"USB\VID_0000&PID_0000\"+name,DeviceClass="HIDClass",TransportService="HidUsb",ConnectorState=connector,ParentChain=new[]{@"USB\VID_0000&PID_0000\"+name,@"USB\ROOT_HUB30\TEST",@"PCI\TEST\ROOT",@"HTREE\ROOT\0"},CompatibleIds=new[]{@"USB\Class_03"},LocationPaths=new[]{"PCIROOT(0)#USBROOT(0)#USB(1)"},Complete=true,ConnectorMatches=1};}
 public static int Main(){var external=Item("EXTERNAL","user_connectable");var builtIn=Item("BUILTIN","internal_port_candidate");var inputs=new[]{external,builtIn};string token=UsbAdmissionPreflight.EvaluateUsbHid(inputs,true,null).TopologyToken;Check(UsbAdmissionRestartSelection.Select(inputs,true,token,new[]{external.Instance},new[]{builtIn.Instance}).State=="restart_selection_ready");Check(UsbAdmissionRestartSelection.Select(inputs,true,token,new[]{builtIn.Instance},new[]{builtIn.Instance}).Instances.Length==0);Check(UsbAdmissionRestartSelection.Select(inputs,true,token,new[]{external.Instance},new[]{external.Instance}).Instances.Length==0);Check(UsbAdmissionRestartSelection.Select(inputs,true,token,new[]{external.Instance,external.Instance},new string[0]).Instances.Length==0);Check(UsbAdmissionRestartSelection.Select(inputs,false,token,new[]{external.Instance},new string[0]).Instances.Length==0);external.ConnectorPartial=true;Check(UsbAdmissionRestartSelection.Select(inputs,true,token,new[]{external.Instance},new string[0]).Instances.Length==0);external.ConnectorPartial=false;external.LocationPaths=new[]{"CHANGED"};Check(UsbAdmissionRestartSelection.Select(inputs,true,token,new[]{external.Instance},new string[0]).Instances.Length==0);Console.WriteLine("PASS exact external USB HID restart selection; internal, protected, duplicate, incomplete and stale topology refused");return 0;}
}
